use vstd::prelude::*;

verus! {
    /// Horizontally stack two vectors by concatenation.
    ///
    /// Ensures that the result’s length is the sum of the inputs’
    /// lengths, and that the result’s content (viewed as a ghost‐sequence)
    /// is exactly `a@ + b@`.
    fn hstack(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
        ensures res.len() == a.len() + b.len(),
        ensures res@ == a@ + b@,
    {
        // Pre‐allocate enough space for all elements to avoid repeated reallocations.
        let mut result = Vec::with_capacity(a.len() + b.len());

        // Copy in all elements from `a` in order.
        result.extend_from_slice(&a);

        // Then copy in all elements from `b` in order.
        result.extend_from_slice(&b);

        result
    }
} // end of verus! block

